#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.41.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.41.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.41.0.js').read_text()
NAV=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-navigation-v1.js').read_text()
IK=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-integrated-knowledge-v1.js').read_text()
PORT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-portability-v1.js').read_text()
REVIEW=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-review-provenance-v1.js').read_text()
def c(x,l):
 if not x: raise SystemExit('FAIL - '+l)
 print('PASS - '+l)
c('Version: 0.41.0' in MAIN,'plugin version')
c((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.41.0','0.40.0','Unified Research Navigation & Information Architecture'),'manifest release lineage')
c((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(35,'sc-workspace-project/20.0','sc-workspace-project-export/20.0'),'schema-stable storage 35 / project 20 / export 20')
c(not MAN['schema_migration_required'] and MAN['migration']['schema_stable'] and MAN['migration']['navigation_only_release'] and not MAN['migration']['canonical_data_rewrite'],'schema-stable navigation boundary')
c(MAN['primary_navigation']==['start','projects','research','review','exchange'],'five primary areas')
c(MAN['navigation_routes']['research']==['research','notebook','knowledge','graph'],'Research contextual routes')
c(MAN['navigation_routes']['review']==['activity','lifecycle','history','changes','reconcile','safety','audit'],'Review contextual routes')
c(MAN['navigation_routes']['exchange']==['interoperability','collaboration','institutional','share'],'Exchange contextual routes')
c('/wp-json/sc-workspace/v1/navigation-contract' in MAN['rest_routes'] and "'/navigation-contract'" in PHP,'navigation REST contract')
c(all(x in NAV for x in ('function areaForView(view)','function defaultView(area)','function viewsForArea(area)','function context(view)','function map()')),'navigation runtime map')
c(all(x in PHP for x in ('data-scw-workspace-area="start"','data-scw-workspace-area="projects"','data-scw-workspace-area="research"','data-scw-workspace-area="review"','data-scw-workspace-area="exchange"')),'primary navigation presentation')
c(all(x in PHP for x in ('data-scw-workspace-context-nav="research"','data-scw-workspace-context-nav="review"','data-scw-workspace-context-nav="exchange"')),'contextual navigation presentation')
c('function syncWorkspaceNavigation()' in JS and 'workspaceContextNavs.forEach' in JS,'browser navigation synchronization')
c(all(x in PHP for x in ('data-scw-research-route="research"','data-scw-research-route="notebook"','data-scw-research-route="knowledge"','data-scw-research-route="graph"')),'task-oriented Research pathways')
g=MAN['governance']; c(g['navigation_derived_from_existing_surfaces'] and not g['navigation_moves_canonical_data'] and not g['navigation_duplicates_canonical_content'],'derived navigation / no canonical data movement')
c(not g['navigation_automatic_semantic_inference'] and not g['navigation_automatic_ai'],'no navigation inference or AI')
c("kind:'object'" in IK and "kind:'notebook-block'" in IK,'v0.40 Integrated Knowledge retained')
c('expectedRevision' in PORT and 'silentLastWriteWins:false' in PORT,'v0.38 conflict-safe notebook sync retained')
c(all(x in REVIEW for x in ('buildReview','buildReconciliation','shadowProvenanceDatabase:false')),'v0.39 Notebook Review & Provenance retained')
c((REG['public_version'],REG['previous_version'])==('0.41.0','0.40.0'),'registry lineage')
c("BACKUP_KEY = 'sc_workspace_registry_backup_v0410'" in REGPHP and 'LEGACY_PENDING_KEY_V0400' in REGPHP,'registry retry lineage')
c((ROOT/'history/release-manifest-v0.40.0.json').exists() and (ROOT/'history/workspace-product-record-v0.40.0.json').exists(),'v0.40 history preserved')
files=list((ROOT/'schemas').glob('*.json'))+[ROOT/'release-manifest-v0.41.0.json',ROOT/'registry/workspace-product-record-v0.41.0.json']
for p in files: json.loads(p.read_text())
print(f'PASS - {len(files)} JSON schema/release records')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.41.0 — Unified Research Navigation & Information Architecture')
